python3 << 'EOF'
import json
import subprocess
import sys

test_cases = [
    # Test 1: Valid 64-char column name
    {
        "name": "64-char column (valid)",
        "input": {
            "pipeline": {"steps": [{"op": "select", "columns": ["a" * 64]}]},
            "dataset": [{"a" * 64: 1}]
        },
        "expected_error": False
    },
    # Test 2: 65-char column name
    {
        "name": "65-char column (invalid)",
        "input": {
            "pipeline": {"steps": [{"op": "select", "columns": ["a" * 65]}]},
            "dataset": []
        },
        "expected_error": True
    },
    # Test 3: Newline in op field
    {
        "name": "Newline in op (invalid)",
        "input": {
            "pipeline": {"steps": [{"op": "select\n", "columns": []}]},
            "dataset": []
        },
        "expected_error": True
    },
    # Test 4: Valid complex pipeline
    {
        "name": "Complex valid pipeline",
        "input": {
            "pipeline": {"steps": [
                {"op": "select", "columns": ["id", "val"]},
                {"op": "filter", "where": "val > 10"},
                {"op": "map", "as": "squared", "expr": "val * val"},
                {
                    "op": "branch",
                    "branches": [
                        {
                            "id": "big",
                            "when": "squared > 100",
                            "steps": [{"op": "limit", "n": 5}]
                        }
                    ]
                }
            ]},
            "dataset": [{"id": 1, "val": 20}]
        },
        "expected_error": False
    },
    # Test 5: Control char in merge.strategy
    {
        "name": "Control char in merge.strategy (invalid)",
        "input": {
            "pipeline": {"steps": [
                {
                    "op": "branch",
                    "branches": [{"when": "true", "steps": []}],
                    "merge": {"strategy": "concat\t"}
                }
            ]},
            "dataset": []
        },
        "expected_error": True
    }
]

passed = 0
failed = 0

for test_case in test_cases:
    result = subprocess.run(
        ["python", "etl_pipeline.py", "--execute"],
        input=json.dumps(test_case["input"]),
        capture_output=True,
        text=True
    )

    output = json.loads(result.stdout)
    has_error = output.get("status") == "error" and output.get("error_code") == "SCHEMA_VALIDATION_FAILED"

    if has_error == test_case["expected_error"]:
        print(f"✓ {test_case['name']}")
        passed += 1
    else:
        print(f"✗ {test_case['name']}")
        print(f"  Output: {result.stdout}")
        failed += 1

print(f"\nPassed: {passed}/{len(test_cases)}")
if failed > 0:
    sys.exit(1)
EOF

