        "name": "Map as field too long",
        "input": {
            "pipeline": {"steps": [
                {"op": "map", "as": "b" * 65, "expr": "x + 1"}
            ]},
            "dataset": []
        },
        "should_fail": True,
        "check_path": "pipeline.steps[0].as"
    },
    {
        "name": "Rename from field with tab",
        "input": {
            "pipeline": {"steps": [
                {"op": "rename", "from": "old\t", "to": "new"}
            ]},
            "dataset": []
        },
        "should_fail": True,
        "check_path": "pipeline.steps[0].from"
    },
    {
        "name": "Branch id with DEL character",
        "input": {
            "pipeline": {"steps": [
                {
                    "op": "branch",
                    "branches": [{"id": "branch" + chr(0x7F), "when": "true", "steps": []}]
                }
            ]},
            "dataset": []
        },
        "should_fail": True,
        "check_path": "pipeline.steps[0].branches[0].id"
    },
    {
        "name": "Complex valid pipeline",
        "input": {
            "pipeline": {"steps": [
                {"op": "select", "columns": ["id", "value"]},
                {"op": "filter", "where": "value > 10"},
                {"op": "map", "as": "squared", "expr": "value * value"},
                {"op": "rename", "mapping": {"value": "val"}},
                {"op": "limit", "n": 100},
                {
                    "op": "branch",
                    "branches": [
                        {"id": "high", "when": "squared > 100", "steps": [{"op": "limit", "n": 5}]},
                        {"when": "otherwise", "steps": [{"op": "limit", "n": 10}]}
